function CatHouseHandbookData:Awake()
    self:ResetAnimData()
    self.item2 = self.RightPanel.transform:Find("Item2")
    self.item3 = self.RightPanel.transform:Find("Item3")
    self.item4 = self.RightPanel.transform:Find("Item4")
    -- self.item4Title = self.Item4:Find("TxtTitle")
    SetButtonAction(self.FontStyleButton1.gameObject, function()
        local geneId = nil
        if self.data[self.preIndex] then
            geneId = checkNumber(self.data[self.preIndex].id)
        end
        CatHouseMgr:GetInstance():ShowRallyListDialog(nil, nil, nil, { geneId = geneId })
    end)
    SetButtonAction(self.FontStyleButton2.gameObject, function()
        local geneId = nil
        if self.data[self.preIndex] then
            geneId = checkNumber(self.data[self.preIndex].id)
        end
        local result = CatHouseMgr:GetInstance():ShowCatListDialogByActionLimit(ConstantsCatHouse.CatActionType.HatchingInvitation,
                ConstantsCatHouse.CatListType.Cultivation, nil, { geneId = geneId }
        )
    end)

    self.preIndex = 0
    local argument = self.controller.Argument
    if not isNull(argument.parameters) then
        local kind = checkInt(argument.parameters.id)

        local filterMB = GetLuaBehaviour(self.CommonFilterNode.gameObject, 'Game.CatHouse.Handbook.UICatFilterMB')
        if not isNull(filterMB) and not isNull(filterMB.Env) then
            ---@type UICatFilterMB
            local filterNodeEnv = filterMB.Env
            filterNodeEnv:SetCallback(function(sortId)
                if sortId == 888 then
                    ---全部的数据
                    self.data = self.originData
                elseif sortId == 889 then
                    ---未解锁的数据
                    local t = {}
                    for i, v in pairs(self.originData) do
                        if not self:IsGenesUnlocked(v.id, kind) then
                            table.insert(t, v)
                        end
                    end
                    self.data = t
                else
                    if kind == ConstantsCatHouse.ScreenCatDataType.Variation then
                        ---变异类型
                        local t = {}
                        for i, v in pairs(self.originData) do
                            ---@type CatHouseHeritableVo
                            local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(v.id)
                            if table.indexof(heritableVo.catId, tostring(sortId)) then
                                table.insert(t, v)
                            end
                        end
                        self.data = t
                    else
                        local t = {}
                        for i, v in pairs(self.originData) do
                            if checkNumber(v.place) == sortId then
                                table.insert(t, v)
                            end
                        end
                        self.data = t
                    end
                end
                ---刷新左侧列表
                self.preIndex = 1
                if #self.data > 0 then
                    KTool.SetActive(self.RightPanel.gameObject, true)
                    ---刷新左侧列表
                    --if kind == ConstantsCatHouse.ScreenCatDataType.Variation then
                    KTool.SetActive(self.ListGridView.gameObject, true)
                    --else
                    --    KTool.SetActive(self.ListView.gameObject, true)
                    --end
                    --if kind == ConstantsCatHouse.ScreenCatDataType.Variation then
                    GameUtils.ReloadData(self.ListGridView, #self.data)
                    self:FreshRightBasicData(self.data[self.preIndex])
                else
                    KTool.SetActive(self.RightPanel.gameObject, false)
                    KTool.SetActive(self.ListGridView.gameObject, false)
                    --if kind == ConstantsCatHouse.ScreenCatDataType.Variation then
                    --    KTool.SetActive(self.ListGridView.gameObject, false)
                    --else
                    --    KTool.SetActive(self.ListView.gameObject, false)
                    --end
                end
            end, kind)
        end
    end

end

