---FreshRightBasicData
---@param vo CatHouseCatDataVo
function CatHouseHandbookData:FreshRightBasicData(vo)
    KTool.SetActive(self.BaseDataEmptyTips.gameObject, vo.kind == ConstantsCatHouse.ScreenCatDataType.Basic)
    if vo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
        ----主题
        local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(vo.id)
        if heritableVo then
            if not self.DataGridView.IsListViewInit then
                self.DataGridView:InitGridView(#heritableVo.formula, Bind(self, self.OnFormulationItemByIndex))
            else
                GameUtils.ReloadData(self.DataGridView, #heritableVo.formula)
            end
        else
            GameUtils.ReloadData(self.DataGridView, 0)
        end
        ---变异主题情况下右侧数据2选1
        if vo.variationKindList and #vo.variationKindList > 0 then
            ---属性加城数据
            KTool.SetActive(self.Item4.gameObject, true)
            KTool.SetActive(self.Item3.gameObject, false)
            --self.item4Title.text = localize('武装属性加成')
            self.Item4Title.Status = 1
            self.additionDataDict = {}
            for i, additionId in pairs(vo.variationKindList) do
                if not self.additionDataDict[tostring(additionId)] then
                    self.additionDataDict[tostring(additionId)] = checkNumber(vo.variationNumList[i])
                else
                    self.additionDataDict[tostring(additionId)] = checkNumber(self.additionDataDict[tostring(additionId)] + checkNumber(vo.variationNumList[i]))
                end
            end
            self.additionData = table.keys(self.additionDataDict)
            table.sort(self.additionData)
            if not self.AdditionListView.IsListViewInit then
                self.AdditionListView:InitListView(#self.additionData, Bind(self, self.OnGetAttributeAdditionByIndex))
            else
                GameUtils.ReloadData(self.AdditionListView, #self.additionData)
            end
        elseif vo.skillIdList and #vo.skillIdList > 0 then
            KTool.SetActive(self.Item4.gameObject, false)
            KTool.SetActive(self.Item3.gameObject, true)
            ---@type CatHouseTechnologyNode
            local env = CfUtils.GetLuaScr(self.Item3.gameObject, CatHouseTechnologyNodePath)
            if isNull(env) then
                return
            end
            env:FreshUI(vo, self:IsGenesUnlocked(vo.id, vo.kind))
        else
            KTool.SetActive(self.Item4.gameObject, false)
            KTool.SetActive(self.Item3.gameObject, false)
        end
    elseif vo.kind == ConstantsCatHouse.ScreenCatDataType.Basic then
        KTool.SetActive(self.Item2.gameObject, false)
    elseif vo.kind == ConstantsCatHouse.ScreenCatDataType.Combination then
        local heritableVo = CatHouseMgr:GetInstance():GetHeritableVoByRefId(vo.id)
        if not self.DataGridView.IsListViewInit then
            self.DataGridView:InitGridView(#heritableVo.formula, Bind(self, self.OnFormulationItemByIndex))
        else
            GameUtils.ReloadData(self.DataGridView, #heritableVo.formula)
        end
    elseif vo.kind == ConstantsCatHouse.ScreenCatDataType.Part then
        local contentTrans = self.Item2.transform:Find("Content")
        local tipsTrans = self.Item2.transform:Find("EmptyTip")
        if contentTrans then
            KTool.SetActive(contentTrans.gameObject, false)
        end
        if tipsTrans then
            KTool.SetActive(tipsTrans.gameObject, true)
        end
        ---处理部件数据的逻辑
        if vo.variationKindList and #vo.variationKindList > 0 then
            KTool.SetActive(self.Item4.gameObject, true)
            ---属性加城数据
            --self.item4Title.text = localize('武装属性加成')
            self.Item4Title.Status = 1
            self.additionDataDict = {}
            for i, additionId in pairs(vo.variationKindList) do
                if not self.additionDataDict[tostring(additionId)] then
                    self.additionDataDict[tostring(additionId)] = checkNumber(vo.variationNumList[i])
                else
                    self.additionDataDict[tostring(additionId)] = checkNumber(self.additionDataDict[tostring(additionId)] + checkNumber(vo.variationNumList[i]))
                end
            end
            self.additionData = table.keys(self.additionDataDict)
            table.sort(self.additionData)
            if not self.AdditionListView.IsListViewInit then
                self.AdditionListView:InitListView(#self.additionData, Bind(self, self.OnGetAttributeAdditionByIndex))
            else
                GameUtils.ReloadData(self.AdditionListView, #self.additionData)
            end
        elseif vo.catSkillIdList and #vo.catSkillIdList > 0 then
            KTool.SetActive(self.Item4.gameObject, true)
            ----技能数据
            self.additionDataDict = nil
            --self.item4Title.text = localize('技能加城')
            self.Item4Title.Status = 2
            self.additionData = vo.catSkillIdList
            if not self.AdditionListView.IsListViewInit then
                self.AdditionListView:InitListView(1, Bind(self, self.OnGetAttributeAdditionByIndex))
            else
                GameUtils.ReloadData(self.AdditionListView, 1)
            end
        else
            KTool.SetActive(self.Item4.gameObject, false)
        end
    end
    self.Item1TxtContent.text = tostring(vo.name)
    CfUtils.FillImage(self.AttributeIcon.gameObject, vo.icon)
    self.AttributeIcon:SetColor(ConstantsCatHouse.ScreenCatDataTypeColor[tostring(vo.kind)])
    local t = CatHouseMgr:GetInstance():GetCatsNameByGeneId(vo.id, vo.kind)
    KTool.GetComponent(self.Item3TxtContent.gameObject, typeof(Text)).text = table.concat(t, '、')
    self:FreshCartModel(vo)
end

---FreshCartModel
---刷新模型信息
---@param vo CatHouseCatDataVo
function CatHouseHandbookData:FreshCartModel(vo)
    local sceneManagement = SceneManagement:GetInstance()
    local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting25)
    if sceneInstance then
        local catGo = sceneInstance:GetCacheObjectByName("CatModel")
        if not isNull(catGo) then
            self:StopCatCo()
            KTool.DestroyGameObjectChildren(catGo)
            local catId = "101"
            ---创建新的猫
            if vo.kind == ConstantsCatHouse.ScreenCatDataType.Combination then
                ---组合
                ---@type CatHouseHeritableVo
                local heritableVo = CatHouseMgr:GetInstance():GetHeritableVoByRefId(vo.id)
                catId = table.takeFirst(heritableVo.catId)
            elseif vo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
                ---@type CatHouseHeritableVo
                local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(vo.id)
                catId = table.takeFirst(heritableVo.catId)
            end
            self.co = cs_coroutine.start(function()
                cs_coroutine.yield_return(CS.Game.Native.Corder.AutoPNGWriter.LoadCatAsync(ConstantsCatHouse.BornType.Adult, catId, false, { vo.id }, catGo, function(go)
                    ---@type UnityEngine.Transform
                    local trans = go.transform
                    go.name = catId
                    trans.position = Vector3.New(0, 0.51, 0.5)
                    trans.localRotation = Quaternion.Euler(0, -130.5, 0)
                    trans.localScale = Vector3.New(2.23, 2.23, 2.23)
                    ---@type HedgehogTeam.EasyTouch.QuickSwipe
                    local quickSwipe = KTool.GetOrAddComponent(go, typeof(QuickSwipe))
                    quickSwipe.quickActionName = "HSwipe"
                    quickSwipe.actionTriggering = 0 --in progress
                    quickSwipe.swipeDirection = 1 -- 水平方向的swipe
                    quickSwipe.enableSimpleAction = true
                    --quickSwipe.enablePickOverUI = true
                    quickSwipe.directAction = 2 ---rotate Local
                    quickSwipe.axesAction = 1 ---Y轴
                    quickSwipe.sensibility = 0.25 ---Y轴
                end))
            end)
        end
    end
end

---OnFormulationItemByIndex
---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function CatHouseHandbookData:OnFormulationItemByIndex(gridView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = gridView:NewListViewItem(CellPrefabName)
    local position = (index + 1)
    ---@type CatHouseCatDataVo
    local vo = self.data[self.preIndex]
    local heritableVo
    local targetId = ConstantsCatHouse.ScreenCatDataType.Basic
    if vo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
        ---变异主题数据
        heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(vo.id)
        targetId = ConstantsCatHouse.ScreenCatDataType.Combination
    else
        ---组合数据
        heritableVo = CatHouseMgr:GetInstance():GetHeritableVoByRefId(vo.id)
    end
    if heritableVo then
        local geneId = heritableVo.formula[position]
        local CatHouseBtnDataNode = cell.transform:Find("CatHouseBtnDataNode")
        if CatHouseBtnDataNode then
            local node = GetLuaBehaviour(CatHouseBtnDataNode.gameObject, CatHouseDataNodeEnvPath)
            ---@type CatHouseDataNode
            local nodeEnv = node.Env
            if nodeEnv then
                nodeEnv:SetBtnCallBack(function()
                    UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseHandbookDataDialog, parameters = { id = targetId, geneId = geneId } }, { { id = Constants.UITypeIds.CatHouseHandbookDataDialog } })
                end)
                nodeEnv:FreshHandBook(geneId)
            end
        end
    end
    return cell
end

function CatHouseHandbookData:OnGetAttributeAdditionByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellPrefabName)
    local attributeNode = cell.transform:Find("CatAttributeNode")
    KTool.SetActive(attributeNode.gameObject, true)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    local position = (index + 1)
    local additionId = self.additionData[position]
    ---@type CatHouseInteractionAttributeNode
    local env = CfUtils.GetLuaScr(attributeNode, PrefabCellEnvPath)
    if isNull(env) then
        return cell
    end
    if isNull(self.additionDataDict) then
        ---技能数据处理, 需要是同一个数据
        local skillVo = CatHouseMgr:GetInstance():GetCatSkillByRefId(additionId)
        if skillVo then
            local attributeVo = CatHouseMgr:GetInstance():GetCatAttributeByRefId(skillVo.attributeId)
            env:FreshBaseUI({ name = skillVo.handbookDesc, picture = attributeVo.picture }, position)
            --env:FreshAttrValue({ num = table.concat(skillVo.numList, '~') })
            env:FreshAttrValue({ num = '' })
        end
    else
        ---属性加城与技能数据处理
        local attributeVo = cardConfMgr:GetInstance():GetBasicAttrByBasicAttrAdditionId(additionId)
        if attributeVo then
            env:FreshBaseUI({ name = attributeVo.name, picture = attributeVo.icon }, position)
            env:FreshAttrValue({ num = '+' .. attribute_format(attributeVo.isConversion, self.additionDataDict[tostring(additionId)]) })
        end
    end
    return cell
end

function CatHouseHandbookData:IsGenesUnlocked(geneId, kind)
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local _, dict = component:GetUnlockGenesByKind(kind)
    local isUnlocked = dict[tostring(geneId)] ~= nil
    return isUnlocked
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopListView2
---@param index number
---@return SuperScrollView.LoopListView2
function CatHouseHandbookData:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellPrefabName)
    local position = (index + 1)
    ---@type CatHouseCatDataVo
    local vo = self.data[position]
    ---@type CatHouseListCellNode
    local env = CfUtils.GetLuaScr(cell, CatHouseListCellNode)
    if isNull(env) then
        return
    end
    env:FreshUI(vo, position, self.preIndex == position, self:IsGenesUnlocked(vo.id, vo.kind), Bind(self, self.FreshRightDetail))
    return cell
end

function CatHouseHandbookData:OnShow()
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument
        if not isNull(argument.parameters) then
            if argument.parameters.geneId then
                local geneId = checkNumber(argument.parameters.geneId)
                for i, v in pairs(self.data) do
                    if checkNumber(v.id) == geneId then
                        self.preIndex = i
                        break
                    end
                end
                local index = math.max(self.preIndex - 1, 0)
                self.ListGridView:MovePanelToItemByIndex(index, 0, 0)
            end
        end

    end))
    return coWait
end

---FreshRightDetail
---@param vo CatHouseCatDataVo
---@param pos number
function CatHouseHandbookData:FreshRightDetail(vo, pos)
    if self.preIndex == pos then
        return
    end
    self.preIndex = pos
    ---刷新左侧列表
    GameUtils.ReloadData(self.ListGridView, #self.data)
    --if vo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
    --    GameUtils.ReloadData(self.ListGridView, #self.data)
    --else
    --    GameUtils.ReloadData(self.ListView, #self.data)
    --end
    self.controller:SetExtraArgument(tostring(vo.id))
    self:FreshRightBasicData(vo)
end

function CatHouseHandbookData:ResetAnimData()
    for i = 1, 8 do
        self["isAnimated"..i] = false
    end
end

---OnIndexRefresh
---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function CatHouseHandbookData:OnIndexRefresh(gridView, index, row, column)
    if index < 0 then
        return nil
    end
    if self.data == nil then
        return nil
    end
    local position = index + 1
    if table.count(self.data) < position then
        return nil
    end
    local cell = gridView:NewListViewItem(CellPrefabName)
    local position = (index + 1)
    ---@type CatHouseCatDataVo
    local vo = self.data[position]
    ---@type CatHouseGridCellNode
    local env = CfUtils.GetLuaScr(cell, CatHouseGridCellNode)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    --是否需要cell的init的逻辑
    local isUnlocked = self:IsGenesUnlocked(vo.id, vo.kind)
    env:FreshCommonUI(vo, position, self.preIndex == position, isUnlocked, Bind(self, self.FreshRightDetail))
    return cell
end

function CatHouseHandbookData:StopCatCo()
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end

function CatHouseHandbookData:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type CameraCustomData
        local customData = KTool.GetComponent(URPCameraController.Instance.mainCamera.gameObject, typeof(CameraCustomData))
        if customData then
            customData.PlaneShadow = CS.CameraCustomData.BaseSettingEnum.Open
        end
        self:StopCatCo()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CatHouseHandbookData